}

// layerProj is the matrix a projection names inside a layer.
func layerProj(l *EncoderLayer, r Proj) (*Linear, error) {
	switch r {
	case ProjFF1A:
		return l.FF1.Linear1, nil
	case ProjFF1B:
		return l.FF1.Linear2, nil
	case ProjQ:
