	case ProjRelK:
		return l.Attn.RelK, nil
	case ProjPW1:
		return l.Conv.PW1, nil
	case ProjPW2:
		return l.Conv.PW2, nil
	case ProjFF2A:
		return l.FF2.Linear1, nil
	case ProjFF2B:
		return l.FF2.Linear2, nil
	}
	return nil, fmt.Errorf("parakeet: no projection %q", r)
