// an A operand's rows are padded (§2.3).
func (g *GPUEncoder) ReadF16(off uint32, rows, cols, lda int) *Mat {
	raw := g.hbuf.ReadUint16At(int(off), (rows-1)*lda+cols)
	out := NewMat(rows, cols)
	for r := 0; r < rows; r++ {
		row, src := out.Row(r), raw[r*lda:]
