cat > shaders/parakeet_lstm_in.comp <<'EOF'
#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
// One LSTM step's A operand: the input vector and the carried hidden state
// laid end to end as a single 2*H-wide fp16 row (SPEECH.md S8).
//
// PyTorch computes a step's gates as `W_ih x + b_ih + W_hh h + b_hh`, two
// matrix-vector products into the same 4H accumulator. Concatenating the two
// operands makes it **one** product against a `[4H, 2H]` weight that is
// `[W_ih | W_hh]` stacked along the reduction axis -- half the dispatches,
// half the intermediates, and a reduction twice as deep, which at M = 1 is
// the direction that helps. The concatenation is done once at upload
// (parakeet/gpudecode.go's lstmWeight) and this pass is what feeds it.
//
// Rows past the first are written as zeros. The GEMM has no bounds check and
// covers whole tiles, so a tile's other 15 or 31 rows multiply *something*;
// making that something zero costs one pass over 40 KB and means the arena
// never carries a stale fp16 denormal into a dispatch that is on the critical
// path of every emitted token.
//
//   pc.inOff   fp32 x, pc.dim wide -- the token embedding for layer 0, the
//              layer below's hidden state for the rest
//   pc.aux0    fp32 h, pc.dim wide, this layer's carried state
//   pc.outOff  fp16 A operand, row stride pc.lda, 2*pc.dim wide
//   pc.tokens  rows to write, i.e. the GEMM's tile height

#include "dit_common.glsl"

layout(binding = 2) writeonly buffer HAct { float16_t hact[]; };

layout(local_size_x = 256) in;

void main() {
    uint r = gl_WorkGroupID.x;
    if (r >= pc.tokens) {
        return;
    }
    uint dst = pc.outOff + r * pc.lda;
    uint width = 2u * pc.dim;
    for (uint i = gl_LocalInvocationID.x; i < width; i += 256u) {
        float v = 0.0;
        if (r == 0u) {
            v = i < pc.dim ? act[pc.inOff + i] : act[pc.aux0 + i - pc.dim];
        }
        hact[dst + i] = float16_t(v);
    }
}
EOF
cat > shaders/parakeet_lstm_gate.comp <<'EOF'
#version 450
// The LSTM cell: four gates out of one 4H-wide product, and the carried state
// updated in place (SPEECH.md S8).
//
// The gate order is PyTorch's, which is the order the weights are stacked in
// and not a convention this code is free to choose: input, forget, cell,
// output, down the rows of both weight matrices. Getting it wrong produces a
// state that decays plausibly rather than an error.
//
// The two bias vectors are already one. PyTorch keeps `bias_ih` and `bias_hh`
// apart even though only their sum can matter at inference -- a CuDNN
// compatibility artefact -- so they are summed at load (parakeet/load.go) and
// this pass reads a single vector.
//
// tanh is written out rather than called. The built-in is free to evaluate
// (e^2x - 1)/(e^2x + 1), which overflows for a gate pre-activation of 90 or
// so; folding the sign and using exp(-2|x|) is bounded everywhere and costs
// the same exponential.
//
//   pc.inOff   fp32 gates [4*dim], row 0 of the GEMM's output
//   pc.wOff    fp32 bias  [4*dim], bias_ih + bias_hh
//   pc.outOff  fp32 h [dim], updated in place
//   pc.aux0    fp32 c [dim], updated in place

#include "dit_common.glsl"

layout(local_size_x = 256) in;

float sigmoid(float x) { return 1.0 / (1.0 + exp(-x)); }

float stable_tanh(float x) {
    float e = exp(-2.0 * abs(x));
    float t = (1.0 - e) / (1.0 + e);
    return x < 0.0 ? -t : t;
}

void main() {
    uint i = gl_GlobalInvocationID.x;
    uint h = pc.dim;
    if (i >= h) {
        return;
    }
    float gi = act[pc.inOff + i] + wbuf[pc.wOff + i];
    float gf = act[pc.inOff + h + i] + wbuf[pc.wOff + h + i];
    float gc = act[pc.inOff + 2u * h + i] + wbuf[pc.wOff + 2u * h + i];
    float go = act[pc.inOff + 3u * h + i] + wbuf[pc.wOff + 3u * h + i];

    float c = sigmoid(gf) * act[pc.aux0 + i] + sigmoid(gi) * stable_tanh(gc);
    act[pc.aux0 + i] = c;
    act[pc.outOff + i] = sigmoid(go) * stable_tanh(c);
}
EOF
cat > shaders/parakeet_joint_sum.comp <<'EOF'
#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
// The transducer's joint, minus its head: one encoder frame added to one
// prediction state, rectified, and narrowed into the head's fp16 A operand
// (SPEECH.md S8).
//
// This is the whole of what "joint" means in an RNN-T: the two towers meet by
// *addition* in a shared 640-wide space, and everything after it is one
// projection to 8198 logits. The frame is chosen by the host -- the TDT
// cursor jumps by the predicted duration rather than by one frame, so which
// row of the projected encoder output this reads is a decision made on the
// host between submits, and arrives as an offset already multiplied out.
//
// The prediction projector's bias is folded in here rather than run as a pass
// of its own over the same 640 floats, the way the two subsampling epilogues
// fold theirs (parakeet_sub_bias.comp).
//
//   pc.inOff   fp32 encoder frame, pc.dim wide, already at its row
//   pc.aux0    fp32 prediction state, pc.dim wide
//   pc.wOff    fp32 bias added to the prediction state, or NO_W
//   pc.outOff  fp16 A operand, row stride pc.lda
//   pc.tokens  rows to write; row 0 is the vector and the rest are zeros

#include "dit_common.glsl"

layout(binding = 2) writeonly buffer HAct { float16_t hact[]; };

layout(local_size_x = 256) in;

void main() {
    uint r = gl_WorkGroupID.x;
    if (r >= pc.tokens) {
        return;
    }
    uint dst = pc.outOff + r * pc.lda;
    for (uint i = gl_LocalInvocationID.x; i < pc.dim; i += 256u) {
        float v = 0.0;
        if (r == 0u) {
            v = act[pc.inOff + i] + act[pc.aux0 + i];
            if (pc.wOff != NO_W) {
                v += wbuf[pc.wOff + i];
            }
            v = max(v, 0.0);
        }
        hact[dst + i] = float16_t(v);
    }
}
EOF
cat > shaders/parakeet_argmax.comp <<'EOF'
#version 450
// The TDT decision: two argmaxes over one logit vector, and the head's bias
// added on the way past (SPEECH.md S8).
//
// The joint's head is [8198, 640] and its output is not one distribution but
// two laid end to end: 8193 token logits with the blank at 8192, then five
// duration logits for [0, 1, 2, 3, 4]. That layout *is* the token-and-duration
// transducer -- emit a token, then advance the encoder cursor by the predicted
// duration instead of by one frame -- and the two argmaxes are independent.
//
// Both indices go back to the host as floats, which is exact: the vocabulary
// is 8193 and float32 is exact on every integer below 2^24. What the host
// does with them is the one rule that joins the two -- a blank asking for a
// zero-frame jump is forced to one, or the loop would not terminate -- and it
// stays there because it is control flow and not arithmetic.
//
// The tie-break is the *lowest* index, at every level of the reduction, which
// is what a serial `for i := 1; ...; if x[i] > x[best]` loop does. It matters:
// a transducer emits a lot of blanks, and the logits at a silent frame are
// close enough together that a different tie-break is a different transcript.
//
// The bias is folded in rather than run as a pass over 8198 floats first,
// which on a loop that runs once per emission is a dispatch saved per token.
//
//   pc.inOff   fp32 logits, pc.dim token logits then pc.aux0 duration logits
//   pc.wOff    fp32 bias over the same layout, or NO_W
//   pc.outOff  fp32 [2]: the token index, then the duration index
//   pc.dim     the vocabulary size, pc.aux0 the number of durations

#include "dit_common.glsl"

layout(local_size_x = 256) in;

shared float sv[256];
shared uint si[256];

float logit(uint i) {
    float v = act[pc.inOff + i];
    if (pc.wOff != NO_W) {
        v += wbuf[pc.wOff + i];
    }
    return v;
}

void main() {
    uint lid = gl_LocalInvocationID.x;
    float bv = -1.0 / 0.0;
    uint bi = pc.dim;
    for (uint i = lid; i < pc.dim; i += 256u) {
        float v = logit(i);
        if (v > bv || (v == bv && i < bi)) {
            bv = v;
            bi = i;
        }
    }
    sv[lid] = bv;
    si[lid] = bi;
    barrier();
    for (uint s = 128u; s > 0u; s >>= 1) {
        if (lid < s) {
            if (sv[lid + s] > sv[lid] || (sv[lid + s] == sv[lid] && si[lid + s] < si[lid])) {
                sv[lid] = sv[lid + s];
                si[lid] = si[lid + s];
            }
        }
        barrier();
    }
    if (lid == 0u) {
        act[pc.outOff] = float(si[0]);
        float db = -1.0 / 0.0;
        uint di = 0u;
        for (uint k = 0u; k < pc.aux0; k++) {
            float v = logit(pc.dim + k);
            if (v > db) {
                db = v;
                di = k;
            }
        }
        act[pc.outOff + 1u] = float(di);
    }
}
EOF
